 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
            member = set(cells)
            layers = []
            depth = 0
            while r0+depth <= r1-depth and c0+depth <= c1-depth:
                vals = []
                top, bot = r0+depth, r1-depth
                left, right = c0+depth, c1-depth
                for x in range(left, right+1):
                    if (top,x) in member: vals.append(grid[top][x])
                    if bot != top and (bot,x) in member: vals.append(grid[bot][x])
                for y in range(top+1, bot):
                    if (y,left) in member: vals.append(grid[y][left])
                    if right != left and (y,right) in member: vals.append(grid[y][right])
                if not vals:
                    break
                color = Counter(vals).most_common(1)[0][0]
                if not layers or color != layers[-1]:
                    layers.append(color)
                depth += 1
            mapping = dict(zip(layers, reversed(layers)))
            for y, x in cells:
                out[y][x] = mapping.get(grid[y][x], grid[y][x])
    return out
